FROM (
    SELECT DISTINCT atom_id AS first_atom, atom_id2 AS second_atom
    FROM connected
    WHERE bond_id IN (
        SELECT bond_id
        FROM bond
        WHERE bond_type = '#'
    )
) AS pairs;

